"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { focusRing, quietFinish, pressScale, primaryFinish, primaryFinishHover } from "./_shared";

/** Mallow IconButton classes: one glyph on the quiet white action by default, round unless `corners` says square. */
const iconButtonVariants = cva(
  [
    "relative inline-flex shrink-0 select-none items-center justify-center",
    pressScale,
    focusRing,
    "disabled:pointer-events-none disabled:opacity-50",
    "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: quietFinish,
        primary: `${primaryFinish} ${primaryFinishHover}`,
        secondary: quietFinish,
        ghost: "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
        destructive: "bg-(image:--danger-face) text-destructive-foreground shadow-xs",
        outline: "bg-transparent text-foreground inset-ring-1 inset-ring-input hover:bg-accent",
      },
      size: {
        xs: "size-7 rounded-sm [&_svg]:size-3.5",
        sm: "size-9 rounded-md [&_svg]:size-4",
        default: "size-12 rounded-lg [&_svg]:size-5",
        lg: "size-14 rounded-xl [&_svg]:size-5",
        xl: "size-16 rounded-2xl [&_svg]:size-6",
      },
      corners: {
        square: "",
        circle: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      corners: "circle",
    },
  },
);

/** Props for the IconButton, which needs an `aria-label` because the glyph carries no text. */
export interface IconButtonProps
  extends Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof iconButtonVariants> {
  className?: string;
}

/** Mallow IconButton on a Base UI button, with the same finishes as the Button. */
const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, corners, ...props }, ref) => (
    <ButtonPrimitive
      ref={ref}
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, size, corners, className }))}
      {...props}
    />
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
